    ).sort(sortVarNames)} />;

const Sizes = () => <TokenDataTable
    caption="Spacing"
    subCaption="Spacing sizes represent a core set of sizing units to match designs to code. Use with `calc()` in CSS to add second units."
    size="md"
    listItems={getTokenListItems('eds-spacing-size', 'size', (name, column) => {
      if (column === 'figma') {
        return 'spacing/size-' + name.split('spacing-size-')[1];
      } else {
        // tailwind or some other value(s) as fallback
        return '*-spacing-size-' + name.split('spacing-size-')[1];
      }
    })} />;

const FontFamilies = () => <TokenDataTable
    caption="Font Families"
    subCaption="These values are used in higher semantic and component tokens and should not be used in custom components directly."
    size="md"
    listItems={getTokenListItems(
      'eds-typography-font-family',
      'size',
      (name, column) => {
        // Hide the one-off offset value
        if (!name.includes('offset')) {
          if (column === 'figma') {
            return (
              'fontFamily/font-family-' + name.slice(name.lastIndexOf('-') + 1)
            );
          } else {
            return 'font-' + name.slice(name.lastIndexOf('-') + 1);
          }
        }
        return '';
      },
    )} />;

